#!/usr/bin/env bash
# Starts a Cubiq server from a Paperclip jar, waits until startup has finished, stops it again and checks
# that it started and stopped cleanly.
#
# Usage: scripts/smoke-test.sh <paperclip-jar> <server-directory> [JVM arguments...]
#
# The server directory is reused if it exists, so the script can simulate first and later starts.
# Set SMOKE_EXPECT_CLEAN_CONFIG=true to fail when the configuration check reports problems, for example
# when the configuration files were generated by the server itself. Set SMOKE_EXPECT_NO_WATCHDOG_REPORTS=true to fail
# when the lifecycle watchdog reports a step that made no progress. Set SMOKE_WAIT_FOR to a text that the server must
# log before it is stopped (SMOKE_WAIT_TIMEOUT seconds at most, default 120).
#
# Running a Minecraft server requires accepting the Minecraft EULA (https://aka.ms/MinecraftEULA).
# This script passes -Dcom.mojang.eula.agree=true; only run it if you accept the EULA.
set -euo pipefail

if [[ $# -lt 2 ]]; then
    echo "Usage: $0 <paperclip-jar> <server-directory> [JVM arguments...]" >&2
    exit 2
fi

jar=$(realpath "$1")
directory=$2
shift 2
startup_timeout=${SMOKE_STARTUP_TIMEOUT:-600}
stop_timeout=${SMOKE_STOP_TIMEOUT:-180}
java=${JAVA:-java}

mkdir -p "$directory"
cd "$directory"
log=smoke-test.log
console=smoke-test.console
rm -f "$log" "$console"
mkfifo "$console"

"$java" -Xms1G -Xmx2G -Dcom.mojang.eula.agree=true "$@" -jar "$jar" --nogui <"$console" >"$log" 2>&1 &
server=$!
# Keep the console open until the server is told to stop
exec 3>"$console"

fail() {
    echo "FAILED: $1" >&2
    echo "----- last 80 log lines -----" >&2
    tail -n 80 "$log" >&2 || true
    kill "$server" 2>/dev/null || true
    exit 1
}

deadline=$((SECONDS + startup_timeout))
until grep -q 'Done (' "$log"; do
    kill -0 "$server" 2>/dev/null || fail "the server exited during startup"
    ((SECONDS < deadline)) || fail "the server did not finish starting within ${startup_timeout}s"
    sleep 1
done
startup_line=$(grep -m 1 'Done (' "$log")

# The configuration check runs right after the Done message; give the server a moment to log it
deadline=$((SECONDS + 30))
until grep -q 'Configuration check' "$log" || ((SECONDS >= deadline)); do
    sleep 1
done

if [[ -n ${SMOKE_WAIT_FOR:-} ]]; then
    deadline=$((SECONDS + ${SMOKE_WAIT_TIMEOUT:-120}))
    until grep -qF -- "$SMOKE_WAIT_FOR" "$log"; do
        kill -0 "$server" 2>/dev/null || fail "the server exited before it logged: $SMOKE_WAIT_FOR"
        ((SECONDS < deadline)) || fail "the server did not log within ${SMOKE_WAIT_TIMEOUT:-120}s: $SMOKE_WAIT_FOR"
        sleep 1
    done
fi

echo "stop" >&3
exec 3>&-
deadline=$((SECONDS + stop_timeout))
while kill -0 "$server" 2>/dev/null; do
    ((SECONDS < deadline)) || fail "the server did not stop within ${stop_timeout}s"
    sleep 1
done
status=0
wait "$server" || status=$?
rm -f "$console"

echo "$startup_line"
grep 'Configuration check' -A 60 "$log" | grep -E 'Configuration check|^\[[0-9:]+ (WARN|INFO)\]: \[Cubiq\] ' || true
echo "Warnings: $(grep -c ' WARN\]' "$log" || true), errors: $(grep -c ' ERROR\]' "$log" || true), exit status: $status"

[[ $status -eq 0 ]] || fail "the server exited with status $status"
grep -q 'Configuration check' "$log" || fail "the configuration check did not run"
if [[ ${SMOKE_EXPECT_CLEAN_CONFIG:-false} == true ]] && grep -q 'Configuration check: found' "$log"; then
    fail "the configuration check reported problems in configuration files generated by the server"
fi
if [[ ${SMOKE_EXPECT_NO_WATCHDOG_REPORTS:-false} == true ]] && grep -q 'Lifecycle watchdog: ' "$log"; then
    fail "the lifecycle watchdog reported a step that made no progress"
fi
